	isAppMode, _ := cmd.Flags().GetBool("is-app-mode")
	if err := validateAitableChartLayout(
		cmd.Context(), baseID, mustGetFlag(cmd, "dashboard-id"), layout, isAppMode); err != nil {
		return err
	}
	toolArgs["layout"] = layout
}
