var cfg map[string]any
if configStr, _ := cmd.Flags().GetString("config"); configStr != "" {
	var err error
	cfg, err = parseAitableJSONObjectFlag("config", configStr, false)
	if err != nil {
		return err
	}
} else {
	cfg = make(map[string]any)
}
if name, _ := cmd.Flags().GetString("name"); name != "" {
	cfg["name"] = name
}
if len(cfg) == 0 {
